solution:
def can_balance(nums):
    n = len(nums)
    for i in range(n):
        left = sum(nums[j] * (i - j) for j in range(i))
        right = sum(nums[j] * (j - i) for j in range(i + 1, n))
        if left == right:
            return True
    return False

